// Exact finite alphabet-bank q13 receiver; six unsupported long words allowed.
// Seven disjoint F-free pairs cover every qualifying action. No short group
// participates in key generation or fit. Native-word and red-rubric alphabets.
#include <bits/stdc++.h>
#include <codecvt>
#include <locale>
using namespace std;
using u64=uint64_t;using A=array<int,29>;using K=array<int,8>;
const string sym="0123456789abcdefghijklmnopqrs";
const u32string runes=U"ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ";
const vector<string> names={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int x){return (x%29+29)%29;}
string file(const string&p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
vector<string> words(const string&s){istringstream f(s);vector<string> v;string w;while(f>>w)v.push_back(w);return v;}
vector<string> fields(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\"([^\"]*)\"");vector<string> v;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i)v.push_back((*i)[1]);return v;}
set<string> D;vector<string> by[64],nof[64];unordered_set<string> lookup;
void spell(const string&s,int i,string w){if(i==(int)s.size()){D.insert(w);return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){auto t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int x=0;x<29;x++)if(t==names[x]){j=x;break;}if(j>=0)spell(s,i+n,w+sym[j]);}}
void dictionary(){istringstream f(file("resources/control/english_wordfreq_textblob.txt"));string l;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(f,l)){if(!regex_match(l,m,re))continue;string s=m[1],v,z;for(char c:s)v+=toupper(c);for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spell(z,0,"");}if(D.size()!=38910)throw runtime_error("dictionary base");for(auto&w:words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added").at(0)))D.insert(w);if(D.size()!=38938)throw runtime_error("dictionary expanded");for(auto&w:D){lookup.insert(w);if(w.size()<64){by[w.size()].push_back(w);if(w.find('0')==string::npos)nof[w.size()].push_back(w);}}}
vector<string> runeGroups(const string&s){wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);vector<string> v;string w;for(auto c:u){size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);return v;}
vector<string> chapter(){auto s=file("resources/transcriptions/lp2-image-corrected.txt");wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);int pg=0;vector<string> v;string w;for(auto c:u){if(c==U'%'){pg++;continue;}if(pg<40||pg>=53)continue;if(c==U'/'||c==U'\n'||c==U'\r'||c==U' '||c==U'\t')continue;size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);int n=0;for(auto&x:v)n+=x.size();if(v.size()!=669||n!=3008)throw runtime_error("chapter shape");return v;}

// Exact q8 phase-specific affine maps, independent starts and odd strides,
// literal F; ciphertext-only pair-cover proof despite <=6 OOV.
constexpr int Q=8,MAPS=812;const array<int,4> strides={1,3,5,7};int mul[MAPS],add[MAPS],iv[MAPS],inverse[29],decodeMap[MAPS][29];
int mapid(int a,int b){if(a<=0||a>=29||b<0||b>=29)throw runtime_error("map");return (a-1)*29+b;}
int solve(int p,int c,int p2,int c2){int a=md(c2-c)*inverse[md(p2-p)]%29;if(!a)throw runtime_error("noninvertible pair");return mapid(a,md(c-a*p));}
void maps(){for(int x=1;x<29;x++)for(int y=1;y<29;y++)if(x*y%29==1)inverse[x]=y;for(int m=0;m<MAPS;m++){mul[m]=m/29+1;add[m]=m%29;iv[m]=inverse[mul[m]];for(int c=0;c<29;c++)decodeMap[m][c]=md(c-add[m])*iv[m]%29;}}
int forward(int m,int p){return (mul[m]*p+add[m])%29;}
string encrypt(const string&w,const K&k,int j,int stride){string c;for(char x:w){int p=sym.find(x);if(!p)c+='0';else{c+=sym[forward(k[j],p)];j=(j+stride)%Q;}}return c;}
bool support(const string&c,const K&k,const string*truth=nullptr){string w(c.size(),'0');function<bool(int,int,int)> rec=[&](int i,int j,int stride){if(i==(int)c.size())return truth?w==*truth:lookup.count(w)>0;int x=sym.find(c[i]);if(!x){w[i]='0';if(rec(i+1,j,stride))return true;}int p=decodeMap[k[j]][x];if(!p)return false;w[i]=sym[p];return rec(i+1,(j+stride)%Q,stride);};for(int stride:strides)for(int j=0;j<Q;j++)if(rec(0,j,stride))return true;return false;}
K norm(K k){K b=k,t;for(int d:strides)for(int p=0;p<Q;p++){for(int j=0;j<Q;j++)t[j]=k[(p+d*j)%Q];b=min(b,t);}return b;}
bool primitive(const K&k){for(int i=0;i<4;i++)if(k[i]!=k[i+4])return true;return false;}
struct Opt{array<uint8_t,Q> p;array<int16_t,Q> m;};struct G{int index;string c;vector<int> cv;array<bool,Q> info{};vector<Opt> opts;};
G group(int i,const string&c){G g;g.index=i;g.c=c;for(char x:c)g.cv.push_back(sym.find(x));for(int j=0;j<Q;j++)g.info[j]=j+Q<(int)c.size()&&c[j]!=c[j+Q];for(auto&w:nof[c.size()]){Opt o;o.m.fill(-1);bool ok=true;for(int j=0;j<Q;j++){int p=sym.find(w[j]);o.p[j]=p;if(j+Q>=(int)c.size())continue;int q=sym.find(w[j+Q]),x=g.cv[j],y=g.cv[j+Q];if((p==q)!=(x==y)){ok=false;break;}if(p!=q)o.m[j]=solve(p,x,q,y);}if(ok)g.opts.push_back(o);}return g;}
struct Pair{int a,b,d,m,at,unknown;};vector<Pair> pairs(const vector<G>&g){vector<Pair> out;for(int i=0;i<(int)g.size();i++)for(int j=i+1;j<(int)g.size();j++)for(int d=0;d<Q;d++)for(int m:strides){int z=0,at=-1;for(int h=0;h<Q;h++){int y=(m*(h-d+Q))%Q;bool a=g[i].info[h],b=g[j].info[y];if(a&&b&&at<0)at=h;if(!a&&!b&&g[i].cv[h]==g[j].cv[y])z++;}if(at>=0&&z<=1)out.push_back({i,j,d,m,at,z});}return out;}
struct Cov{int max=0;uint64_t nodes=0;};Cov coverage(int n,const vector<Pair>&pairs){bool ok[24][24][Q][Q]={};for(auto&p:pairs){ok[p.a][p.b][p.d][p.m]=true;ok[p.b][p.a][(p.m*(Q-p.d))%Q][p.m]=true;}Cov c;vector<array<int,3>> sel;function<void(int)> dfs=[&](int i){c.nodes++;c.max=max(c.max,(int)sel.size());if(i>=n||(int)sel.size()+n-i<=c.max)return;int ph=sel.empty()?1:Q;for(int p=0;p<ph;p++)for(int m:strides){if(sel.empty()&&m!=1)continue;bool good=true;for(auto [j,q,d]:sel)if(ok[j][i][(d*(p-q+Q))%Q][(d*m)%Q]){good=false;break;}if(good){sel.push_back({i,p,m});dfs(i+1);sel.pop_back();}}dfs(i+1);};dfs(0);return c;}
struct KH{size_t operator()(const K&k)const{uint64_t h=0x123456789abcdefULL;for(auto x:k)h=(h^(x+0x9e3779b97f4a7c15ULL))*0xbf58476d1ce4e5b9ULL;return h^(h>>31);}};
unordered_set<u64> coded[64];void codes(){for(int n=1;n<64;n++)if(n<=13)for(auto&w:nof[n]){u64 v=0;for(char x:w)v=v*29+sym.find(x);coded[n].insert(v);}}
bool fast(const G&g,const K&k){for(int stride:strides)for(int ph=0;ph<Q;ph++){u64 id=0;bool ok=true;for(int i=0;i<(int)g.cv.size();i++){int p=decodeMap[k[(i*stride+ph)%Q]][g.cv[i]];if(!p){ok=false;break;}id=id*29+p;}if(ok&&coded[g.cv.size()].count(id))return true;}return false;}
struct Fit{K k;int train;};struct Stats{uint64_t joined=0,consistent=0,keys=0,dups=0,fastPass=0;int maxBad=0;vector<Fit> fits;Cov cov;int paircount=0;};
Stats recover(const vector<string>&C,const vector<int>&eligible){vector<G> gs;for(int i:eligible)gs.push_back(group(i,C[i]));auto ps=pairs(gs);Stats s;s.cov=coverage(gs.size(),ps);s.paircount=ps.size();if(s.cov.max>=(int)gs.size()-6)throw runtime_error("anchor cover not proved");unordered_set<K,KH> seen;seen.reserve(1000000);
auto validate=[&](K k){if(!primitive(k))return;k=norm(k);if(!seen.insert(k).second){s.dups++;return;}s.keys++;int bad=0;for(auto&g:gs)if(!fast(g,k)&&++bad>6)return;s.fastPass++;bad=0;int tr=0;for(auto&c:C){if(support(c,k))tr++;else if(++bad>6)return;}if(tr>=int(C.size())-6)s.fits.push_back({k,tr});};
for(auto &pair:ps){auto&a=gs[pair.a];auto&b=gs[pair.b];int d=pair.d,m=pair.m,h0=pair.at,y0=(m*(h0-d+Q))%Q;vector<const Opt*> index[MAPS];for(auto&x:b.opts){int m=x.m[y0];if(m<0)throw runtime_error("informative");index[m].push_back(&x);}for(auto&x:a.opts){int id=x.m[h0];if(id<0)throw runtime_error("informative");for(auto*yp:index[id]){s.joined++;auto&y=*yp;K k;k.fill(-1);int missing=-1,mp=-1,mc=-1;bool ok=true;for(int h=0;h<Q;h++){int j=(m*(h-d+Q))%Q,p=x.p[h],q=y.p[j],c=a.cv[h],e=b.cv[j],ma=x.m[h],mb=y.m[j];if(ma>=0){if((mb>=0&&ma!=mb)||forward(ma,q)!=e){ok=false;break;}k[h]=ma;}else if(mb>=0){if(forward(mb,p)!=c){ok=false;break;}k[h]=mb;}else if(p==q){if(c!=e){ok=false;break;}if(missing>=0)throw runtime_error("multiple missing");missing=h;mp=p;mc=c;}else{if(c==e){ok=false;break;}k[h]=solve(p,c,q,e);}}if(!ok)continue;s.consistent++;if(missing<0)validate(k);else for(int a=1;a<29;a++){k[missing]=mapid(a,md(mc-a*mp));validate(k);}}}}
return s;}
template<class T>string ar(const T&v){string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=to_string(+x);}return s+"]";}
int main(int argc,char**argv){dictionary();maps();codes();string mode=argc>1?argv[1]:"0";bool control=mode!="original";auto f=file("im-results/lp2-shared-gp29-q8-affine-long-fixtures.json");auto C=words(fields(f,"originalTrain").at(0));vector<int>eligible;for(int j=0;j<24;j++)if(C[j].find('0')==string::npos)eligible.push_back(j);if(eligible.size()!=15)throw runtime_error("profile");vector<string>H,T,HT;K key{};vector<int>omit;
if(control){int i=stoi(mode);auto t=words(fields(f,"truth").at(i%2));T.assign(t.begin(),t.begin()+24);HT.assign(t.begin()+24,t.end());mt19937 rng(0x8af32900u+i);for(auto&x:key)x=rng()%MAPS;if(!primitive(key))key[7]=(key[7]+1)%MAPS;auto v=eligible;shuffle(v.begin(),v.end(),rng);omit.assign(v.begin(),v.begin()+6);sort(omit.begin(),omit.end());for(int j=0;j<24;j++){bool ff=find(eligible.begin(),eligible.end(),j)!=eligible.end(),bad=find(omit.begin(),omit.end(),j)!=omit.end();int n=C[j].size();string orig=T[j];for(int tries=0;;tries++){if(tries>100000)throw runtime_error("plant retries");if(bad){T[j].clear();for(int x=0;x<n;x++)T[j]+=sym[1+rng()%28];}else if(tries||!lookup.count(orig)||(ff&&orig.find('0')!=string::npos)){auto&v=ff?nof[n]:by[n];T[j]=v[rng()%v.size()];}C[j]=encrypt(T[j],key,rng()%Q,strides[rng()%4]);if(ff&&C[j].find('0')!=string::npos)continue;if(bad&&support(C[j],key))continue;break;}}for(auto&w:HT)H.push_back(encrypt(w,key,rng()%Q,strides[rng()%4]));}
else{auto a=chapter();vector<string>L;for(auto&w:a)(w.size()>=10?L:H).push_back(w);auto v=C;sort(v.begin(),v.end());sort(L.begin(),L.end());if(v!=L)throw runtime_error("original anchor profile");}
auto R=recover(C,eligible);ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"dictionary\":"<<D.size()<<",\"budget\":6,\"eligible\":"<<eligible.size()<<",\"qualifying_pairs\":"<<R.paircount<<",\"coverage_max_independent\":"<<R.cov.max<<",\"coverage_nodes\":"<<R.cov.nodes<<",\"joined\":"<<R.joined<<",\"consistent\":"<<R.consistent<<",\"keys\":"<<R.keys<<",\"duplicates\":"<<R.dups<<",\"fast_pass\":"<<R.fastPass<<",\"fit_count\":"<<R.fits.size()<<",\"omitted\":"<<ar(omit)<<",\"fits\":[";int exact=0,ht=0,tr=0;for(int i=0;i<(int)R.fits.size();i++){auto&x=R.fits[i];if(control&&x.k==norm(key)){exact++;for(int j=0;j<24;j++)tr+=support(C[j],x.k,&T[j]);for(int j=0;j<(int)H.size();j++)ht+=support(H[j],x.k,&HT[j]);}if(i>=20)continue;int held=0;for(auto&w:H)held+=support(w,x.k);if(i)o<<",";o<<"{\"key\":"<<ar(x.k)<<",\"training\":"<<x.train<<",\"held\":"<<held<<"}";}o<<"],\"exact\":"<<exact<<",\"train_truth\":"<<tr<<",\"held_truth\":"<<ht<<",\"held_count\":"<<H.size()<<"}";cout<<"FINAL "<<o.str()<<endl;if(const char*p=getenv("SFT_OUTPUT")){ofstream f(p);f<<o.str()<<endl;}return 0;}
